  background: transparent;
}
.btn-outline:hover { background: var(--color-primary); color: var(--color-white); }
.btn-white {
  background: var(--color-white);
  color: var(--color-primary);
}
.btn-white:hover { background: var(--color-light); }
.btn-link {
  padding: 0;
  color: var(--color-primary);
  font-weight: 600;
  font-size: 0.9375rem;
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
