}
.btn-link:hover { gap: 0.625rem; }
.btn-link .arrow { transition: transform var(--transition); }
.btn-link:hover .arrow { transform: translateX(3px); }

/* --- Header / Navigation --- */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
