/* ============================================
   GlobalStone — Corporate Website Styles
   ============================================ */

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --color-primary: #003F2D;
  --color-primary-dark: #012A2D;
  --color-navy: #0A1628;
  --color-accent: #C5A572;
  --color-accent-hover: #b8954f;
  --color-teal: #1A6B5A;
  --color-light: #F7F7F5;
  --color-gray: #E6E6E6;
  --color-gray-dark: #6B7280;
  --color-text: #1F2937;
  --color-text-light: #9CA3AF;
  --color-white: #FFFFFF;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-serif: 'Playfair Display', Georgia, 'Times New Roman', serif;
  --max-width: 1280px;
  --header-height: 80px;
  --transition: 0.3s ease;
}

html { scroll-behavior: smooth; font-size: 16px; }

body {
  font-family: var(--font-sans);
  color: var(--color-text);
  background: var(--color-white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
img { max-width: 100%; height: auto; display: block; }
ul, ol { list-style: none; }
button { cursor: pointer; border: none; background: none; font-family: inherit; }
input { font-family: inherit; }

.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 2rem;
}

/* --- Typography --- */
h1, h2, h3 { font-family: var(--font-serif); font-weight: 700; line-height: 1.2; color: var(--color-navy); }
h1 { font-size: clamp(2.25rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.75rem, 3.5vw, 2.5rem); }
h3 { font-size: clamp(1.25rem, 2vw, 1.5rem); }
h4 { font-size: 1.125rem; font-weight: 600; }
p { color: var(--color-gray-dark); line-height: 1.7; }

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.875rem 2rem;
  font-size: 0.9375rem;
  font-weight: 600;
  border-radius: 4px;
  transition: all var(--transition);
  letter-spacing: 0.01em;
}
.btn-primary {
  background: var(--color-primary);
  color: var(--color-white);
}
.btn-primary:hover { background: var(--color-primary-dark); }
.btn-accent {
  background: var(--color-accent);
  color: var(--color-navy);
}
.btn-accent:hover { background: var(--color-accent-hover); }
.btn-outline {
  border: 2px solid var(--color-primary);
  color: var(--color-primary);
  background: transparent;
}
.btn-outline:hover { background: var(--color-primary); color: var(--color-white); }
.btn-white {
  background: var(--color-white);
  color: var(--color-primary);
}
.btn-white:hover { background: var(--color-light); }
.btn-link {
  padding: 0;
  color: var(--color-primary);
  font-weight: 600;
  font-size: 0.9375rem;
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  transition: gap var(--transition);
}
.btn-link:hover { gap: 0.625rem; }
.btn-link .arrow { transition: transform var(--transition); }
.btn-link:hover .arrow { transform: translateX(3px); }

/* --- Header / Navigation --- */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: var(--header-height);
  background: var(--color-white);
  border-bottom: 1px solid var(--color-gray);
  z-index: 1000;
  transition: box-shadow var(--transition);
}
.header.scrolled { box-shadow: 0 2px 20px rgba(0,0,0,0.08); }

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 2rem;
}

.logo {
  font-family: var(--font-serif);
  font-size: 1.625rem;
  font-weight: 700;
  color: var(--color-primary);
  letter-spacing: -0.02em;
}
.logo span { color: var(--color-accent); }

.nav-desktop { display: flex; align-items: center; gap: 0; height: 100%; }
.nav-desktop > li { height: 100%; display: flex; align-items: center; }
.nav-desktop > li > a {
  padding: 0 1.25rem;
  height: 100%;
  display: flex;
  align-items: center;
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--color-text);
  position: relative;
  transition: color var(--transition);
}
.nav-desktop > li > a:hover,
.nav-desktop > li > a.active { color: var(--color-primary); }
.nav-desktop > li > a::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 1.25rem;
  right: 1.25rem;
  height: 3px;
  background: var(--color-primary);
  transform: scaleX(0);
  transition: transform var(--transition);
}
.nav-desktop > li > a:hover::after,
.nav-desktop > li > a.active::after { transform: scaleX(1); }

.nav-services-trigger { cursor: pointer; }
.nav-services-trigger .chevron {
  display: inline-block;
  margin-left: 4px;
  transition: transform var(--transition);
  font-size: 0.625rem;
}
.nav-services-trigger.open .chevron { transform: rotate(180deg); }

/* Mega Menu */
.mega-menu {
  position: absolute;
  top: var(--header-height);
  left: 0;
  right: 0;
  background: var(--color-white);
  border-top: 3px solid var(--color-primary);
  box-shadow: 0 20px 60px rgba(0,0,0,0.12);
  opacity: 0;
  visibility: hidden;
  transform: translateY(-8px);
  transition: all 0.25s ease;
  z-index: 999;
}
.mega-menu.open {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}
.mega-menu-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 2.5rem 2rem;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
}
.mega-menu-col h4 {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--color-primary);
  margin-bottom: 1.25rem;
  padding-bottom: 0.75rem;
  border-bottom: 2px solid var(--color-gray);
}
.mega-menu-col ul li { margin-bottom: 0.25rem; }
.mega-menu-col ul li a {
  display: block;
  padding: 0.5rem 0.75rem;
  font-size: 0.9375rem;
  color: var(--color-text);
  border-radius: 4px;
  transition: all var(--transition);
}
.mega-menu-col ul li a:hover {
  background: var(--color-light);
  color: var(--color-primary);
  padding-left: 1rem;
}

/* Mobile Nav */
.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  width: 28px;
  padding: 4px 0;
  z-index: 1001;
}
.hamburger span {
  display: block;
  height: 2px;
  background: var(--color-navy);
  border-radius: 2px;
  transition: all var(--transition);
}
.hamburger.open span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
.hamburger.open span:nth-child(2) { opacity: 0; }
.hamburger.open span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }

.nav-mobile {
  display: none;
  position: fixed;
  top: var(--header-height);
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--color-white);
  overflow-y: auto;
  z-index: 998;
  padding: 1rem 0;
}
.nav-mobile.open { display: block; }
.nav-mobile > ul > li > a,
.nav-mobile > ul > li > button {
  display: flex;
  justify-content: space-between;
  align-items: center;
  width: 100%;
  padding: 1rem 2rem;
  font-size: 1.0625rem;
  font-weight: 500;
  color: var(--color-text);
  border-bottom: 1px solid var(--color-gray);
  text-align: left;
}
.accordion-trigger .chevron-mobile {
  font-size: 0.75rem;
  transition: transform var(--transition);
}
.accordion-trigger.open .chevron-mobile { transform: rotate(180deg); }
.accordion-content {
  display: none;
  background: var(--color-light);
  padding: 0.5rem 0;
}
.accordion-content.open { display: block; }
.accordion-content h5 {
  padding: 0.75rem 2.5rem 0.25rem;
  font-size: 0.6875rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--color-primary);
  font-weight: 700;
}
.accordion-content a {
  display: block;
  padding: 0.625rem 3rem;
  font-size: 0.9375rem;
  color: var(--color-text);
}
.accordion-content a:hover { color: var(--color-primary); background: var(--color-gray); }

/* --- Hero Section --- */
.hero {
  margin-top: var(--header-height);
  position: relative;
  min-height: 560px;
  display: flex;
  align-items: center;
  overflow: hidden;
}
.hero-bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, var(--color-navy) 0%, var(--color-primary-dark) 60%, var(--color-primary) 100%);
}
.hero-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.03'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
}
.hero-content {
  position: relative;
  z-index: 2;
  max-width: 640px;
  padding: 4rem 0;
}
.hero-label {
  display: inline-block;
  padding: 0.375rem 1rem;
  background: rgba(197, 165, 114, 0.2);
  color: var(--color-accent);
  font-size: 0.8125rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  border-radius: 2px;
  margin-bottom: 1.5rem;
}
.hero h1 { color: var(--color-white); margin-bottom: 1.25rem; }
.hero p { color: rgba(255,255,255,0.8); font-size: 1.125rem; margin-bottom: 2rem; }

.hero-small { min-height: 380px; }
.hero-small .hero-content { padding: 3rem 0; }

/* --- Featured Insights --- */
.featured-insights {
  padding: 5rem 0;
  background: var(--color-white);
}
.section-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  margin-bottom: 3rem;
  flex-wrap: wrap;
  gap: 1rem;
}
.section-header h2 { margin-bottom: 0; }

.insights-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
}
.insight-card {
  border-radius: 8px;
  overflow: hidden;
  border: 1px solid var(--color-gray);
  transition: all var(--transition);
  background: var(--color-white);
}
.insight-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 12px 40px rgba(0,0,0,0.1);
}
.insight-card-img {
  height: 200px;
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-primary-dark) 100%);
  position: relative;
  overflow: hidden;
}
.insight-card-img::after {
  content: '';
  position: absolute;
  inset: 0;
  background: url("data:image/svg+xml,%3Csvg width='400' height='200' viewBox='0 0 400 200' xmlns='http://www.w3.org/2000/svg'%3E%3Crect width='400' height='200' fill='none'/%3E%3Ccircle cx='300' cy='100' r='120' fill='rgba(255,255,255,0.04)'/%3E%3Ccircle cx='100' cy='150' r='80' fill='rgba(255,255,255,0.03)'/%3E%3C/svg%3E");
}
.insight-card-tag {
  position: absolute;
  top: 1rem;
  left: 1rem;
  padding: 0.25rem 0.75rem;
  background: var(--color-accent);
  color: var(--color-navy);
  font-size: 0.75rem;
  font-weight: 600;
  border-radius: 2px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  z-index: 1;
}
.insight-card-body { padding: 1.5rem; }
.insight-card-body h3 { font-size: 1.125rem; margin-bottom: 0.75rem; }
.insight-card-body p { font-size: 0.875rem; margin-bottom: 1rem; }
.insight-card-meta { font-size: 0.8125rem; color: var(--color-text-light); }

/* --- Announcement Banner --- */
.announcement {
  background: var(--color-accent);
  padding: 1.25rem 0;
}
.announcement-inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
}
.announcement p {
  font-weight: 600;
  color: var(--color-navy);
  font-size: 1.0625rem;
}
.announcement .btn {
  background: var(--color-navy);
  color: var(--color-white);
  padding: 0.625rem 1.5rem;
  font-size: 0.875rem;
}
.announcement .btn:hover { background: var(--color-primary-dark); }

/* --- About Statement --- */
.about-statement {
  padding: 6rem 0;
  background: var(--color-light);
}
.about-inner {
  max-width: 800px;
}
.about-inner h2 { margin-bottom: 1.5rem; }
.about-inner p { font-size: 1.125rem; margin-bottom: 2rem; }

/* --- What We Do (Tabs) --- */
.what-we-do {
  padding: 6rem 0;
  background: var(--color-white);
}
.tabs-container {
  display: flex;
  gap: 0;
  margin-top: 3rem;
  border: 1px solid var(--color-gray);
  border-radius: 8px;
  overflow: hidden;
  min-height: 320px;
}
.tabs-nav {
  width: 280px;
  flex-shrink: 0;
  background: var(--color-navy);
}
.tab-btn {
  display: block;
  width: 100%;
  padding: 1.5rem 2rem;
  text-align: left;
  font-size: 1rem;
  font-weight: 500;
  color: rgba(255,255,255,0.6);
  border-bottom: 1px solid rgba(255,255,255,0.08);
  transition: all var(--transition);
  position: relative;
}
.tab-btn:hover { color: rgba(255,255,255,0.9); background: rgba(255,255,255,0.05); }
.tab-btn.active {
  color: var(--color-white);
  background: var(--color-primary);
}
.tab-btn.active::before {
  content: '';
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 4px;
  background: var(--color-accent);
}
.tab-panel {
  display: none;
  padding: 3rem;
  flex: 1;
  animation: fadeIn 0.3s ease;
}
.tab-panel.active { display: flex; flex-direction: column; justify-content: center; }
.tab-panel h3 { margin-bottom: 1rem; font-size: 1.75rem; }
.tab-panel p { font-size: 1.0625rem; margin-bottom: 1.5rem; max-width: 520px; }
.tab-panel ul { margin-bottom: 1.5rem; }
.tab-panel ul li {
  padding: 0.375rem 0;
  padding-left: 1.25rem;
  position: relative;
  color: var(--color-gray-dark);
}
.tab-panel ul li::before {
  content: '';
  position: absolute;
  left: 0;
  top: 0.75rem;
  width: 6px;
  height: 6px;
  background: var(--color-primary);
  border-radius: 50%;
}

@keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }

/* --- Newsletter --- */
.newsletter {
  padding: 5rem 0;
  background: var(--color-primary);
  color: var(--color-white);
}
.newsletter-inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 2rem;
}
.newsletter-text h2 { color: var(--color-white); margin-bottom: 0.5rem; }
.newsletter-text p { color: rgba(255,255,255,0.8); }
.newsletter-form {
  display: flex;
  gap: 0.75rem;
}
.newsletter-form input {
  padding: 0.875rem 1.25rem;
  border: 2px solid rgba(255,255,255,0.3);
  border-radius: 4px;
  background: rgba(255,255,255,0.1);
  color: var(--color-white);
  font-size: 0.9375rem;
  width: 300px;
  transition: border-color var(--transition);
}
.newsletter-form input::placeholder { color: rgba(255,255,255,0.5); }
.newsletter-form input:focus { outline: none; border-color: var(--color-accent); }

/* --- Latest Insights --- */
.latest-insights {
  padding: 5rem 0;
  background: var(--color-white);
}
.insights-list { display: flex; flex-direction: column; gap: 1.5rem; }
.insight-row {
  display: flex;
  gap: 2rem;
  padding: 1.5rem;
  border: 1px solid var(--color-gray);
  border-radius: 8px;
  transition: all var(--transition);
  align-items: center;
}
.insight-row:hover {
  box-shadow: 0 4px 20px rgba(0,0,0,0.06);
  border-color: var(--color-primary);
}
.insight-row-img {
  width: 160px;
  height: 100px;
  flex-shrink: 0;
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-teal) 100%);
  border-radius: 4px;
}
.insight-row-body { flex: 1; }
.insight-row-tag {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--color-primary);
  margin-bottom: 0.5rem;
}
.insight-row-body h3 { font-size: 1.0625rem; margin-bottom: 0.375rem; }
.insight-row-body .date { font-size: 0.8125rem; color: var(--color-text-light); }

/* --- Our Commitment --- */
.commitment {
  padding: 6rem 0;
  background: var(--color-light);
}
.commitment-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
  margin-top: 3rem;
}
.commitment-card {
  background: var(--color-white);
  padding: 2rem;
  border-radius: 8px;
  border: 1px solid var(--color-gray);
  transition: all var(--transition);
}
.commitment-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 12px 40px rgba(0,0,0,0.08);
}
.commitment-icon {
  width: 48px;
  height: 48px;
  background: var(--color-primary);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.25rem;
}
.commitment-icon svg { width: 24px; height: 24px; fill: var(--color-white); }
.commitment-card h3 { font-size: 1.125rem; margin-bottom: 0.75rem; }
.commitment-card p { font-size: 0.875rem; margin-bottom: 1.25rem; }

/* --- Footer --- */
.footer {
  background: var(--color-navy);
  color: rgba(255,255,255,0.7);
  padding: 4rem 0 2rem;
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(3, 1fr);
  gap: 3rem;
  margin-bottom: 3rem;
}
.footer-brand .logo { margin-bottom: 1rem; color: var(--color-white); }
.footer-brand p { font-size: 0.875rem; line-height: 1.6; color: rgba(255,255,255,0.6); max-width: 300px; }
.footer-col h4 {
  color: var(--color-white);
  font-size: 0.8125rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 1.25rem;
  font-weight: 600;
}
.footer-col a {
  display: block;
  padding: 0.375rem 0;
  font-size: 0.875rem;
  color: rgba(255,255,255,0.6);
  transition: color var(--transition);
}
.footer-col a:hover { color: var(--color-accent); }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 2rem;
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 1rem;
}
.footer-bottom p { font-size: 0.8125rem; color: rgba(255,255,255,0.4); }
.footer-legal { display: flex; gap: 1.5rem; }
.footer-legal a { font-size: 0.8125rem; color: rgba(255,255,255,0.4); }
.footer-legal a:hover { color: rgba(255,255,255,0.7); }

/* --- Services Page --- */
.intro-statement {
  padding: 5rem 0;
  background: var(--color-white);
}
.intro-statement .intro-inner { max-width: 800px; }
.intro-statement h2 { margin-bottom: 1.25rem; }
.intro-statement p { font-size: 1.125rem; }

.service-categories {
  padding: 5rem 0;
  background: var(--color-light);
}
.services-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
}
.service-card {
  background: var(--color-white);
  padding: 2.5rem;
  border-radius: 8px;
  border: 1px solid var(--color-gray);
  transition: all var(--transition);
  display: flex;
  flex-direction: column;
}
.service-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 12px 40px rgba(0,0,0,0.08);
  border-color: var(--color-primary);
}
.service-card-icon {
  width: 56px;
  height: 56px;
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-teal) 100%);
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.5rem;
}
.service-card-icon svg { width: 28px; height: 28px; fill: var(--color-white); }
.service-card h3 { font-size: 1.25rem; margin-bottom: 1rem; }
.service-card p { font-size: 0.9375rem; margin-bottom: 1.5rem; flex: 1; }

/* --- Capabilities Grid --- */
.capabilities {
  padding: 5rem 0;
  background: var(--color-light);
}
.capabilities-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
  margin-top: 3rem;
}
.capability-card {
  background: var(--color-white);
  padding: 2rem;
  border-radius: 8px;
  border: 1px solid var(--color-gray);
  transition: all var(--transition);
  border-top: 4px solid var(--color-primary);
}
.capability-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 30px rgba(0,0,0,0.08);
}
.capability-card h3 { font-size: 1.125rem; margin-bottom: 0.75rem; }
.capability-card p { font-size: 0.875rem; }

/* Featured Topics */
.featured-topics {
  padding: 5rem 0;
  background: var(--color-white);
}
.topics-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.5rem;
  margin-top: 2.5rem;
}
.topic-card {
  padding: 2rem 1.5rem;
  text-align: center;
  border-radius: 8px;
  background: var(--color-navy);
  color: var(--color-white);
  transition: all var(--transition);
}
.topic-card:hover { transform: translateY(-4px); background: var(--color-primary-dark); }
.topic-card h3 { color: var(--color-white); font-size: 1.0625rem; }

/* Deal Flow CTA */
.deal-flow {
  padding: 5rem 0;
  background: linear-gradient(135deg, var(--color-navy) 0%, var(--color-primary-dark) 100%);
  text-align: center;
}
.deal-flow h2 { color: var(--color-white); margin-bottom: 1rem; }
.deal-flow p { color: rgba(255,255,255,0.8); font-size: 1.125rem; max-width: 600px; margin: 0 auto 2rem; }

/* Testimonial */
.testimonial {
  padding: 5rem 0;
  background: var(--color-white);
}
.testimonial-inner {
  max-width: 800px;
  margin: 0 auto;
  text-align: center;
}
.testimonial-quote {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  line-height: 1.6;
  color: var(--color-navy);
  margin-bottom: 1.5rem;
  position: relative;
}
.testimonial-quote::before {
  content: '\201C';
  font-size: 4rem;
  color: var(--color-accent);
  position: absolute;
  top: -1.5rem;
  left: -1rem;
  font-family: var(--font-serif);
}
.testimonial-author { font-weight: 600; color: var(--color-primary); }
.testimonial-role { font-size: 0.875rem; color: var(--color-gray-dark); }

/* Property Types CTA */
.property-types {
  padding: 5rem 0;
  background: var(--color-light);
}
.property-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 1.5rem;
  margin-top: 2.5rem;
}
.property-card {
  text-align: center;
  padding: 2rem 1rem;
  background: var(--color-white);
  border-radius: 8px;
  border: 1px solid var(--color-gray);
  transition: all var(--transition);
}
.property-card:hover { border-color: var(--color-primary); transform: translateY(-4px); box-shadow: 0 8px 24px rgba(0,0,0,0.06); }
.property-card-icon {
  width: 48px;
  height: 48px;
  margin: 0 auto 1rem;
  background: var(--color-light);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}
.property-card-icon svg { width: 24px; height: 24px; fill: var(--color-primary); }
.property-card h4 { font-size: 0.9375rem; }

/* Related Services */
.related-services {
  padding: 5rem 0;
  background: var(--color-white);
}
.related-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 2rem;
  margin-top: 2.5rem;
}
.related-card {
  padding: 2rem;
  border: 1px solid var(--color-gray);
  border-radius: 8px;
  transition: all var(--transition);
}
.related-card:hover { border-color: var(--color-primary); box-shadow: 0 4px 20px rgba(0,0,0,0.06); }
.related-card h3 { font-size: 1.125rem; margin-bottom: 0.5rem; }
.related-card p { font-size: 0.875rem; margin-bottom: 1rem; }

/* Related Insights */
.related-insights {
  padding: 5rem 0;
  background: var(--color-light);
}

/* Partners Carousel */
.featured-partners { padding: 5rem 0; background: var(--color-white); }
.carousel-container { position: relative; overflow: hidden; margin-top: 2.5rem; }
.carousel-track {
  display: flex;
  transition: transform 0.5s ease;
}
.carousel-slide {
  min-width: 100%;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
  padding: 0 0.25rem;
}
.partner-card {
  background: var(--color-light);
  padding: 2rem;
  border-radius: 8px;
  text-align: center;
}
.partner-logo {
  width: 80px;
  height: 80px;
  margin: 0 auto 1rem;
  background: var(--color-white);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 2px solid var(--color-gray);
}
.partner-logo span {
  font-family: var(--font-serif);
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--color-primary);
}
.partner-card h4 { margin-bottom: 0.5rem; }
.partner-card p { font-size: 0.875rem; }
.carousel-controls {
  display: flex;
  justify-content: center;
  gap: 1rem;
  margin-top: 2rem;
}
.carousel-btn {
  width: 44px;
  height: 44px;
  border: 2px solid var(--color-gray);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition);
  font-size: 1.125rem;
  color: var(--color-text);
}
.carousel-btn:hover { border-color: var(--color-primary); color: var(--color-primary); }

/* Partnership Highlight */
.partnership {
  padding: 5rem 0;
  background: var(--color-white);
}
.partnership-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}
.partnership-visual {
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-teal) 100%);
  border-radius: 12px;
  height: 320px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}
.partnership-visual::after {
  content: '';
  position: absolute;
  inset: 0;
  background: url("data:image/svg+xml,%3Csvg width='200' height='200' viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Crect width='200' height='200' fill='none'/%3E%3Ccircle cx='100' cy='100' r='80' fill='rgba(255,255,255,0.06)'/%3E%3Ccircle cx='160' cy='40' r='40' fill='rgba(255,255,255,0.04)'/%3E%3C/svg%3E");
}
.partnership-stats {
  position: relative;
  z-index: 1;
  display: flex;
  gap: 3rem;
}
.stat { text-align: center; }
.stat-number {
  font-family: var(--font-serif);
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--color-white);
}
.stat-label { font-size: 0.8125rem; color: rgba(255,255,255,0.8); margin-top: 0.25rem; }
.partnership-content h2 { margin-bottom: 1.25rem; }
.partnership-content p { font-size: 1.0625rem; margin-bottom: 1.5rem; }

/* What We Do section in sub-pages */
.what-we-do-subpage { padding: 5rem 0; background: var(--color-white); }
.what-we-do-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 2rem;
  margin-top: 2.5rem;
}

/* --- Responsive --- */
@media (max-width: 1024px) {
  .insights-grid { grid-template-columns: repeat(2, 1fr); }
  .services-grid { grid-template-columns: repeat(2, 1fr); }
  .capabilities-grid { grid-template-columns: repeat(2, 1fr); }
  .commitment-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .topics-grid { grid-template-columns: repeat(2, 1fr); }
  .property-grid { grid-template-columns: repeat(3, 1fr); }
  .partnership-inner { grid-template-columns: 1fr; }
}

@media (max-width: 768px) {
  .nav-desktop { display: none; }
  .hamburger { display: flex; }
  .mega-menu { display: none; }

  .hero { min-height: 420px; }
  .hero-small { min-height: 320px; }
  .hero h1 { font-size: 2rem; }

  .insights-grid { grid-template-columns: 1fr; }
  .services-grid { grid-template-columns: 1fr; }
  .capabilities-grid { grid-template-columns: 1fr; }
  .commitment-grid { grid-template-columns: 1fr; }

  .tabs-container { flex-direction: column; }
  .tabs-nav { width: 100%; display: flex; overflow-x: auto; }
  .tab-btn { white-space: nowrap; padding: 1rem 1.5rem; border-bottom: none; border-right: 1px solid rgba(255,255,255,0.08); }
  .tab-btn.active::before { display: none; }
  .tab-panel { padding: 2rem; }

  .newsletter-inner { flex-direction: column; text-align: center; }
  .newsletter-form { flex-direction: column; width: 100%; }
  .newsletter-form input { width: 100%; }

  .insight-row { flex-direction: column; }
  .insight-row-img { width: 100%; height: 160px; }

  .footer-grid { grid-template-columns: 1fr; gap: 2rem; }
  .footer-bottom { flex-direction: column; text-align: center; }
  .footer-legal { justify-content: center; flex-wrap: wrap; }

  .section-header { flex-direction: column; align-items: flex-start; }

  .announcement-inner { flex-direction: column; text-align: center; }

  .topics-grid { grid-template-columns: 1fr; }
  .property-grid { grid-template-columns: repeat(2, 1fr); }
  .related-grid { grid-template-columns: 1fr; }

  .carousel-slide { grid-template-columns: 1fr; }

  .partnership-visual { height: 240px; }
  .what-we-do-grid { grid-template-columns: 1fr; }
}

@media (max-width: 480px) {
  .container { padding: 0 1.25rem; }
  .property-grid { grid-template-columns: 1fr; }
}

/* ============================================
   GlobalStone — Corporate Website Styles
   ============================================ */

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --color-primary: #003F2D;
  --color-primary-dark: #012A2D;
  --color-navy: #0A1628;
  --color-accent: #C5A572;
  --color-accent-hover: #b8954f;
  --color-teal: #1A6B5A;
  --color-light: #F7F7F5;
  --color-gray: #E6E6E6;
  --color-gray-dark: #6B7280;
  --color-text: #1F2937;
  --color-text-light: #9CA3AF;
  --color-white: #FFFFFF;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-serif: 'Playfair Display', Georgia, 'Times New Roman', serif;
  --max-width: 1280px;
  --header-height: 80px;
  --transition: 0.3s ease;
}

html { scroll-behavior: smooth; font-size: 16px; }

body {
  font-family: var(--font-sans);
  color: var(--color-text);
  background: var(--color-white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
img { max-width: 100%; height: auto; display: block; }
ul, ol { list-style: none; }
button { cursor: pointer; border: none; background: none; font-family: inherit; }
input { font-family: inherit; }

.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 2rem;
}

/* --- Typography --- */
h1, h2, h3 { font-family: var(--font-serif); font-weight: 700; line-height: 1.2; color: var(--color-navy); }
h1 { font-size: clamp(2.25rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.75rem, 3.5vw, 2.5rem); }
h3 { font-size: clamp(1.25rem, 2vw, 1.5rem); }
h4 { font-size: 1.125rem; font-weight: 600; }
p { color: var(--color-gray-dark); line-height: 1.7; }

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.875rem 2rem;
  font-size: 0.9375rem;
  font-weight: 600;
  border-radius: 4px;
  transition: all var(--transition);
  letter-spacing: 0.01em;
}
.btn-primary {
  background: var(--color-primary);
  color: var(--color-white);
}
.btn-primary:hover { background: var(--color-primary-dark); }
.btn-accent {
  background: var(--color-accent);
  color: var(--color-navy);
}
.btn-accent:hover { background: var(--color-accent-hover); }
.btn-outline {
  border: 2px solid var(--color-primary);
  color: var(--color-primary);
  background: transparent;
}
.btn-outline:hover { background: var(--color-primary); color: var(--color-white); }
.btn-white {
  background: var(--color-white);
  color: var(--color-primary);
}
.btn-white:hover { background: var(--color-light); }
.btn-link {
  padding: 0;
  color: var(--color-primary);
  font-weight: 600;
  font-size: 0.9375rem;
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  transition: gap var(--transition);
}
.btn-link:hover { gap: 0.625rem; }
.btn-link .arrow { transition: transform var(--transition); }
.btn-link:hover .arrow { transform: translateX(3px); }

/* --- Header / Navigation --- */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: var(--header-height);
  background: var(--color-white);
  border-bottom: 1px solid var(--color-gray);
  z-index: 1000;
  transition: box-shadow var(--transition);
}
.header.scrolled { box-shadow: 0 2px 20px rgba(0,0,0,0.08); }

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 2rem;
}

.logo {
  font-family: var(--font-serif);
  font-size: 1.625rem;
  font-weight: 700;
  color: var(--color-primary);
  letter-spacing: -0.02em;
}
.logo span { color: var(--color-accent); }

.nav-desktop { display: flex; align-items: center; gap: 0; height: 100%; }
.nav-desktop > li { height: 100%; display: flex; align-items: center; }
.nav-desktop > li > a {
  padding: 0 1.25rem;
  height: 100%;
  display: flex;
  align-items: center;
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--color-text);
  position: relative;
  transition: color var(--transition);
}
.nav-desktop > li > a:hover,
.nav-desktop > li > a.active { color: var(--color-primary); }
.nav-desktop > li > a::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 1.25rem;
  right: 1.25rem;
  height: 3px;
  background: var(--color-primary);
  transform: scaleX(0);
  transition: transform var(--transition);
}
.nav-desktop > li > a:hover::after,
.nav-desktop > li > a.active::after { transform: scaleX(1); }

.nav-services-trigger { cursor: pointer; }
.nav-services-trigger .chevron {
  display: inline-block;
  margin-left: 4px;
  transition: transform var(--transition);
  font-size: 0.625rem;
}
.nav-services-trigger.open .chevron { transform: rotate(180deg); }

/* Mega Menu */
.mega-menu {
  position: absolute;
  top: var(--header-height);
  left: 0;
  right: 0;
  background: var(--color-white);
  border-top: 3px solid var(--color-primary);
  box-shadow: 0 20px 60px rgba(0,0,0,0.12);
  opacity: 0;
  visibility: hidden;
  transform: translateY(-8px);
  transition: all 0.25s ease;
  z-index: 999;
}
.mega-menu.open {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}
.mega-menu-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 2.5rem 2rem;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
}
.mega-menu-col h4 {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--color-primary);
  margin-bottom: 1.25rem;
  padding-bottom: 0.75rem;
  border-bottom: 2px solid var(--color-gray);
}
.mega-menu-col ul li { margin-bottom: 0.25rem; }
.mega-menu-col ul li a {
  display: block;
  padding: 0.5rem 0.75rem;
  font-size: 0.9375rem;
  color: var(--color-text);
  border-radius: 4px;
  transition: all var(--transition);
}
.mega-menu-col ul li a:hover {
  background: var(--color-light);
  color: var(--color-primary);
  padding-left: 1rem;
}

/* Mobile Nav */
.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  width: 28px;
  padding: 4px 0;
  z-index: 1001;
}
.hamburger span {
  display: block;
  height: 2px;
  background: var(--color-navy);
  border-radius: 2px;
  transition: all var(--transition);
}
.hamburger.open span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
.hamburger.open span:nth-child(2) { opacity: 0; }
.hamburger.open span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }

.nav-mobile {
  display: none;
  position: fixed;
  top: var(--header-height);
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--color-white);
  overflow-y: auto;
  z-index: 998;
  padding: 1rem 0;
}
.nav-mobile.open { display: block; }
.nav-mobile > ul > li > a,
.nav-mobile > ul > li > button {
  display: flex;
  justify-content: space-between;
  align-items: center;
  width: 100%;
  padding: 1rem 2rem;
  font-size: 1.0625rem;
  font-weight: 500;
  color: var(--color-text);
  border-bottom: 1px solid var(--color-gray);
  text-align: left;
}
.accordion-trigger .chevron-mobile {
  font-size: 0.75rem;
  transition: transform var(--transition);
}
.accordion-trigger.open .chevron-mobile { transform: rotate(180deg); }
.accordion-content {
  display: none;
  background: var(--color-light);
  padding: 0.5rem 0;
}
.accordion-content.open { display: block; }
.accordion-content h5 {
  padding: 0.75rem 2.5rem 0.25rem;
  font-size: 0.6875rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--color-primary);
  font-weight: 700;
}
.accordion-content a {
  display: block;
  padding: 0.625rem 3rem;
  font-size: 0.9375rem;
  color: var(--color-text);
}
.accordion-content a:hover { color: var(--color-primary); background: var(--color-gray); }

/* --- Hero Section --- */
.hero {
  margin-top: var(--header-height);
  position: relative;
  min-height: 560px;
  display: flex;
  align-items: center;
  overflow: hidden;
}
.hero-bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, var(--color-navy) 0%, var(--color-primary-dark) 60%, var(--color-primary) 100%);
}
.hero-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.03'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
}
.hero-content {
  position: relative;
  z-index: 2;
  max-width: 640px;
  padding: 4rem 0;
}
.hero-label {
  display: inline-block;
  padding: 0.375rem 1rem;
  background: rgba(197, 165, 114, 0.2);
  color: var(--color-accent);
  font-size: 0.8125rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  border-radius: 2px;
  margin-bottom: 1.5rem;
}
.hero h1 { color: var(--color-white); margin-bottom: 1.25rem; }
.hero p { color: rgba(255,255,255,0.8); font-size: 1.125rem; margin-bottom: 2rem; }

.hero-small { min-height: 380px; }
.hero-small .hero-content { padding: 3rem 0; }

/* --- Featured Insights --- */
.featured-insights {
  padding: 5rem 0;
  background: var(--color-white);
}
.section-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  margin-bottom: 3rem;
  flex-wrap: wrap;
  gap: 1rem;
}
.section-header h2 { margin-bottom: 0; }

.insights-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
}
.insight-card {
  border-radius: 8px;
  overflow: hidden;
  border: 1px solid var(--color-gray);
  transition: all var(--transition);
  background: var(--color-white);
}
.insight-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 12px 40px rgba(0,0,0,0.1);
}
.insight-card-img {
  height: 200px;
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-primary-dark) 100%);
  position: relative;
  overflow: hidden;
}
.insight-card-img::after {
  content: '';
  position: absolute;
  inset: 0;
  background: url("data:image/svg+xml,%3Csvg width='400' height='200' viewBox='0 0 400 200' xmlns='http://www.w3.org/2000/svg'%3E%3Crect width='400' height='200' fill='none'/%3E%3Ccircle cx='300' cy='100' r='120' fill='rgba(255,255,255,0.04)'/%3E%3Ccircle cx='100' cy='150' r='80' fill='rgba(255,255,255,0.03)'/%3E%3C/svg%3E");
}
.insight-card-tag {
  position: absolute;
  top: 1rem;
  left: 1rem;
  padding: 0.25rem 0.75rem;
  background: var(--color-accent);
  color: var(--color-navy);
  font-size: 0.75rem;
  font-weight: 600;
  border-radius: 2px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  z-index: 1;
}
.insight-card-body { padding: 1.5rem; }
.insight-card-body h3 { font-size: 1.125rem; margin-bottom: 0.75rem; }
.insight-card-body p { font-size: 0.875rem; margin-bottom: 1rem; }
.insight-card-meta { font-size: 0.8125rem; color: var(--color-text-light); }

/* --- Announcement Banner --- */
.announcement {
  background: var(--color-accent);
  padding: 1.25rem 0;
}
.announcement-inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
}
.announcement p {
  font-weight: 600;
  color: var(--color-navy);
  font-size: 1.0625rem;
}
.announcement .btn {
  background: var(--color-navy);
  color: var(--color-white);
  padding: 0.625rem 1.5rem;
  font-size: 0.875rem;
}
.announcement .btn:hover { background: var(--color-primary-dark); }

/* --- About Statement --- */
.about-statement {
  padding: 6rem 0;
  background: var(--color-light);
}
.about-inner {
  max-width: 800px;
}
.about-inner h2 { margin-bottom: 1.5rem; }
.about-inner p { font-size: 1.125rem; margin-bottom: 2rem; }

/* --- What We Do (Tabs) --- */
.what-we-do {
  padding: 6rem 0;
  background: var(--color-white);
}
.tabs-container {
  display: flex;
  gap: 0;
  margin-top: 3rem;
  border: 1px solid var(--color-gray);
  border-radius: 8px;
  overflow: hidden;
  min-height: 320px;
}
.tabs-nav {
  width: 280px;
  flex-shrink: 0;
  background: var(--color-navy);
}
.tab-btn {
  display: block;
  width: 100%;
  padding: 1.5rem 2rem;
  text-align: left;
  font-size: 1rem;
  font-weight: 500;
  color: rgba(255,255,255,0.6);
  border-bottom: 1px solid rgba(255,255,255,0.08);
  transition: all var(--transition);
  position: relative;
}
.tab-btn:hover { color: rgba(255,255,255,0.9); background: rgba(255,255,255,0.05); }
.tab-btn.active {
  color: var(--color-white);
  background: var(--color-primary);
}
.tab-btn.active::before {
  content: '';
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 4px;
  background: var(--color-accent);
}
.tab-panel {
  display: none;
  padding: 3rem;
  flex: 1;
  animation: fadeIn 0.3s ease;
}
.tab-panel.active { display: flex; flex-direction: column; justify-content: center; }
.tab-panel h3 { margin-bottom: 1rem; font-size: 1.75rem; }
.tab-panel p { font-size: 1.0625rem; margin-bottom: 1.5rem; max-width: 520px; }
.tab-panel ul { margin-bottom: 1.5rem; }
.tab-panel ul li {
  padding: 0.375rem 0;
  padding-left: 1.25rem;
  position: relative;
  color: var(--color-gray-dark);
}
.tab-panel ul li::before {
  content: '';
  position: absolute;
  left: 0;
  top: 0.75rem;
  width: 6px;
  height: 6px;
  background: var(--color-primary);
  border-radius: 50%;
}

@keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }

/* --- Newsletter --- */
.newsletter {
  padding: 5rem 0;
  background: var(--color-primary);
  color: var(--color-white);
}
.newsletter-inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 2rem;
}
.newsletter-text h2 { color: var(--color-white); margin-bottom: 0.5rem; }
.newsletter-text p { color: rgba(255,255,255,0.8); }
.newsletter-form {
  display: flex;
  gap: 0.75rem;
}
.newsletter-form input {
  padding: 0.875rem 1.25rem;
  border: 2px solid rgba(255,255,255,0.3);
  border-radius: 4px;
  background: rgba(255,255,255,0.1);
  color: var(--color-white);
  font-size: 0.9375rem;
  width: 300px;
  transition: border-color var(--transition);
}
.newsletter-form input::placeholder { color: rgba(255,255,255,0.5); }
.newsletter-form input:focus { outline: none; border-color: var(--color-accent); }

/* --- Latest Insights --- */
.latest-insights {
  padding: 5rem 0;
  background: var(--color-white);
}
.insights-list { display: flex; flex-direction: column; gap: 1.5rem; }
.insight-row {
  display: flex;
  gap: 2rem;
  padding: 1.5rem;
  border: 1px solid var(--color-gray);
  border-radius: 8px;
  transition: all var(--transition);
  align-items: center;
}
.insight-row:hover {
  box-shadow: 0 4px 20px rgba(0,0,0,0.06);
  border-color: var(--color-primary);
}
.insight-row-img {
  width: 160px;
  height: 100px;
  flex-shrink: 0;
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-teal) 100%);
  border-radius: 4px;
}
.insight-row-body { flex: 1; }
.insight-row-tag {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--color-primary);
  margin-bottom: 0.5rem;
}
.insight-row-body h3 { font-size: 1.0625rem; margin-bottom: 0.375rem; }
.insight-row-body .date { font-size: 0.8125rem; color: var(--color-text-light); }

/* --- Our Commitment --- */
.commitment {
  padding: 6rem 0;
  background: var(--color-light);
}
.commitment-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
  margin-top: 3rem;
}
.commitment-card {
  background: var(--color-white);
  padding: 2rem;
  border-radius: 8px;
  border: 1px solid var(--color-gray);
  transition: all var(--transition);
}
.commitment-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 12px 40px rgba(0,0,0,0.08);
}
.commitment-icon {
  width: 48px;
  height: 48px;
  background: var(--color-primary);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.25rem;
}
.commitment-icon svg { width: 24px; height: 24px; fill: var(--color-white); }
.commitment-card h3 { font-size: 1.125rem; margin-bottom: 0.75rem; }
.commitment-card p { font-size: 0.875rem; margin-bottom: 1.25rem; }

/* --- Footer --- */
.footer {
  background: var(--color-navy);
  color: rgba(255,255,255,0.7);
  padding: 4rem 0 2rem;
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(3, 1fr);
  gap: 3rem;
  margin-bottom: 3rem;
}
.footer-brand .logo { margin-bottom: 1rem; color: var(--color-white); }
.footer-brand p { font-size: 0.875rem; line-height: 1.6; color: rgba(255,255,255,0.6); max-width: 300px; }
.footer-col h4 {
  color: var(--color-white);
  font-size: 0.8125rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 1.25rem;
  font-weight: 600;
}
.footer-col a {
  display: block;
  padding: 0.375rem 0;
  font-size: 0.875rem;
  color: rgba(255,255,255,0.6);
  transition: color var(--transition);
}
.footer-col a:hover { color: var(--color-accent); }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 2rem;
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 1rem;
}
.footer-bottom p { font-size: 0.8125rem; color: rgba(255,255,255,0.4); }
.footer-legal { display: flex; gap: 1.5rem; }
.footer-legal a { font-size: 0.8125rem; color: rgba(255,255,255,0.4); }
.footer-legal a:hover { color: rgba(255,255,255,0.7); }

/* --- Services Page --- */
.intro-statement {
  padding: 5rem 0;
  background: var(--color-white);
}
.intro-statement .intro-inner { max-width: 800px; }
.intro-statement h2 { margin-bottom: 1.25rem; }
.intro-statement p { font-size: 1.125rem; }

.service-categories {
  padding: 5rem 0;
  background: var(--color-light);
}
.services-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
}
.service-card {
  background: var(--color-white);
  padding: 2.5rem;
  border-radius: 8px;
  border: 1px solid var(--color-gray);
  transition: all var(--transition);
  display: flex;
  flex-direction: column;
}
.service-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 12px 40px rgba(0,0,0,0.08);
  border-color: var(--color-primary);
}
.service-card-icon {
  width: 56px;
  height: 56px;
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-teal) 100%);
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.5rem;
}
.service-card-icon svg { width: 28px; height: 28px; fill: var(--color-white); }
.service-card h3 { font-size: 1.25rem; margin-bottom: 1rem; }
.service-card p { font-size: 0.9375rem; margin-bottom: 1.5rem; flex: 1; }

/* --- Capabilities Grid --- */
.capabilities {
  padding: 5rem 0;
  background: var(--color-light);
}
.capabilities-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
  margin-top: 3rem;
}
.capability-card {
  background: var(--color-white);
  padding: 2rem;
  border-radius: 8px;
  border: 1px solid var(--color-gray);
  transition: all var(--transition);
  border-top: 4px solid var(--color-primary);
}
.capability-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 30px rgba(0,0,0,0.08);
}
.capability-card h3 { font-size: 1.125rem; margin-bottom: 0.75rem; }
.capability-card p { font-size: 0.875rem; }

/* Featured Topics */
.featured-topics {
  padding: 5rem 0;
  background: var(--color-white);
}
.topics-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.5rem;
  margin-top: 2.5rem;
}
.topic-card {
  padding: 2rem 1.5rem;
  text-align: center;
  border-radius: 8px;
  background: var(--color-navy);
  color: var(--color-white);
  transition: all var(--transition);
}
.topic-card:hover { transform: translateY(-4px); background: var(--color-primary-dark); }
.topic-card h3 { color: var(--color-white); font-size: 1.0625rem; }

/* Deal Flow CTA */
.deal-flow {
  padding: 5rem 0;
  background: linear-gradient(135deg, var(--color-navy) 0%, var(--color-primary-dark) 100%);
  text-align: center;
}
.deal-flow h2 { color: var(--color-white); margin-bottom: 1rem; }
.deal-flow p { color: rgba(255,255,255,0.8); font-size: 1.125rem; max-width: 600px; margin: 0 auto 2rem; }

/* Testimonial */
.testimonial {
  padding: 5rem 0;
  background: var(--color-white);
}
.testimonial-inner {
  max-width: 800px;
  margin: 0 auto;
  text-align: center;
}
.testimonial-quote {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  line-height: 1.6;
  color: var(--color-navy);
  margin-bottom: 1.5rem;
  position: relative;
}
.testimonial-quote::before {
  content: '\201C';
  font-size: 4rem;
  color: var(--color-accent);
  position: absolute;
  top: -1.5rem;
  left: -1rem;
  font-family: var(--font-serif);
}
.testimonial-author { font-weight: 600; color: var(--color-primary); }
.testimonial-role { font-size: 0.875rem; color: var(--color-gray-dark); }

/* Property Types CTA */
.property-types {
  padding: 5rem 0;
  background: var(--color-light);
}
.property-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 1.5rem;
  margin-top: 2.5rem;
}
.property-card {
  text-align: center;
  padding: 2rem 1rem;
  background: var(--color-white);
  border-radius: 8px;
  border: 1px solid var(--color-gray);
  transition: all var(--transition);
}
.property-card:hover { border-color: var(--color-primary); transform: translateY(-4px); box-shadow: 0 8px 24px rgba(0,0,0,0.06); }
.property-card-icon {
  width: 48px;
  height: 48px;
  margin: 0 auto 1rem;
  background: var(--color-light);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}
.property-card-icon svg { width: 24px; height: 24px; fill: var(--color-primary); }
.property-card h4 { font-size: 0.9375rem; }

/* Related Services */
.related-services {
  padding: 5rem 0;
  background: var(--color-white);
}
.related-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 2rem;
  margin-top: 2.5rem;
}
.related-card {
  padding: 2rem;
  border: 1px solid var(--color-gray);
  border-radius: 8px;
  transition: all var(--transition);
}
.related-card:hover { border-color: var(--color-primary); box-shadow: 0 4px 20px rgba(0,0,0,0.06); }
.related-card h3 { font-size: 1.125rem; margin-bottom: 0.5rem; }
.related-card p { font-size: 0.875rem; margin-bottom: 1rem; }

/* Related Insights */
.related-insights {
  padding: 5rem 0;
  background: var(--color-light);
}

/* Partners Carousel */
.featured-partners { padding: 5rem 0; background: var(--color-white); }
.carousel-container { position: relative; overflow: hidden; margin-top: 2.5rem; }
.carousel-track {
  display: flex;
  transition: transform 0.5s ease;
}
.carousel-slide {
  min-width: 100%;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
  padding: 0 0.25rem;
}
.partner-card {
  background: var(--color-light);
  padding: 2rem;
  border-radius: 8px;
  text-align: center;
}
.partner-logo {
  width: 80px;
  height: 80px;
  margin: 0 auto 1rem;
  background: var(--color-white);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 2px solid var(--color-gray);
}
.partner-logo span {
  font-family: var(--font-serif);
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--color-primary);
}
.partner-card h4 { margin-bottom: 0.5rem; }
.partner-card p { font-size: 0.875rem; }
.carousel-controls {
  display: flex;
  justify-content: center;
  gap: 1rem;
  margin-top: 2rem;
}
.carousel-btn {
  width: 44px;
  height: 44px;
  border: 2px solid var(--color-gray);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition);
  font-size: 1.125rem;
  color: var(--color-text);
}
.carousel-btn:hover { border-color: var(--color-primary); color: var(--color-primary); }

/* Partnership Highlight */
.partnership {
  padding: 5rem 0;
  background: var(--color-white);
}
.partnership-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}
.partnership-visual {
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-teal) 100%);
  border-radius: 12px;
  height: 320px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}
.partnership-visual::after {
  content: '';
  position: absolute;
  inset: 0;
  background: url("data:image/svg+xml,%3Csvg width='200' height='200' viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Crect width='200' height='200' fill='none'/%3E%3Ccircle cx='100' cy='100' r='80' fill='rgba(255,255,255,0.06)'/%3E%3Ccircle cx='160' cy='40' r='40' fill='rgba(255,255,255,0.04)'/%3E%3C/svg%3E");
}
.partnership-stats {
  position: relative;
  z-index: 1;
  display: flex;
  gap: 3rem;
}
.stat { text-align: center; }
.stat-number {
  font-family: var(--font-serif);
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--color-white);
}
.stat-label { font-size: 0.8125rem; color: rgba(255,255,255,0.8); margin-top: 0.25rem; }
.partnership-content h2 { margin-bottom: 1.25rem; }
.partnership-content p { font-size: 1.0625rem; margin-bottom: 1.5rem; }

/* What We Do section in sub-pages */
.what-we-do-subpage { padding: 5rem 0; background: var(--color-white); }
.what-we-do-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 2rem;
  margin-top: 2.5rem;
}

/* --- Responsive --- */
@media (max-width: 1024px) {
  .insights-grid { grid-template-columns: repeat(2, 1fr); }
  .services-grid { grid-template-columns: repeat(2, 1fr); }
  .capabilities-grid { grid-template-columns: repeat(2, 1fr); }
  .commitment-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .topics-grid { grid-template-columns: repeat(2, 1fr); }
  .property-grid { grid-template-columns: repeat(3, 1fr); }
  .partnership-inner { grid-template-columns: 1fr; }
}

@media (max-width: 768px) {
  .nav-desktop { display: none; }
  .hamburger { display: flex; }
  .mega-menu { display: none; }

  .hero { min-height: 420px; }
  .hero-small { min-height: 320px; }
  .hero h1 { font-size: 2rem; }

  .insights-grid { grid-template-columns: 1fr; }
  .services-grid { grid-template-columns: 1fr; }
  .capabilities-grid { grid-template-columns: 1fr; }
  .commitment-grid { grid-template-columns: 1fr; }

  .tabs-container { flex-direction: column; }
  .tabs-nav { width: 100%; display: flex; overflow-x: auto; }
  .tab-btn { white-space: nowrap; padding: 1rem 1.5rem; border-bottom: none; border-right: 1px solid rgba(255,255,255,0.08); }
  .tab-btn.active::before { display: none; }
  .tab-panel { padding: 2rem; }

  .newsletter-inner { flex-direction: column; text-align: center; }
  .newsletter-form { flex-direction: column; width: 100%; }
  .newsletter-form input { width: 100%; }

  .insight-row { flex-direction: column; }
  .insight-row-img { width: 100%; height: 160px; }

  .footer-grid { grid-template-columns: 1fr; gap: 2rem; }
  .footer-bottom { flex-direction: column; text-align: center; }
  .footer-legal { justify-content: center; flex-wrap: wrap; }

  .section-header { flex-direction: column; align-items: flex-start; }

  .announcement-inner { flex-direction: column; text-align: center; }

  .topics-grid { grid-template-columns: 1fr; }
  .property-grid { grid-template-columns: repeat(2, 1fr); }
  .related-grid { grid-template-columns: 1fr; }

  .carousel-slide { grid-template-columns: 1fr; }

  .partnership-visual { height: 240px; }
  .what-we-do-grid { grid-template-columns: 1fr; }
}

@media (max-width: 480px) {
  .container { padding: 0 1.25rem; }
  .property-grid { grid-template-columns: 1fr; }
}

